function metrics(s){const w=sorted(s.weights),last=w.at(-1),first=w[0],initial=s.profile.initialWeight??first?.value??null,current=last?.value??null;const fat=[...s.weights,...s.measures].filter(r=>r.fat!=null);const start=first?.date;const prior=w.filter(r=>epoch(r.date)<=epoch(today())-7*DAY).at(-1);return {current,initial,goal:s.profile.goal,change:current!=null&&initial!=null?current-initial:null,bmi:current!=null&&s.profile.height?current/(s.profile.height/100)**2:null,fat:sorted(fat).at(-1)?.fat??null,days:start?Math.floor((epoch(today())-epoch(start))/DAY)+1:0,weekly:current!=null&&prior&&last&&epoch(last.date)>epoch(today())-7*DAY?current-prior.value:null,progress:initial!=null&&s.profile.goal!=null&&current!=null?(initial===s.profile.goal?(current===s.profile.goal?100:0):Math.min(100,Math.max(0,(initial-current)/(initial-s.profile.goal)*100))):null}}
