function nextReminders(s,now=new Date()){const d=today(now),all=[{id:'weight',title:'Registrar peso',time:s.settings.weightTime,repeat:'daily',date:d,enabled:s.profile.tracking?.weight!==false},{id:'measure',title:'Registrar medidas',time:s.settings.measureTime,repeat:'weekly',weekday:Number(s.settings.measureDay),date:d,enabled:s.profile.tracking?.measures!==false},...s.reminders];return all.filter(r=>r.enabled).map(r=>{const first=r.date>d?r.date:d;let x=new Date((r.repeat==='once'?r.date:first)+'T'+r.time+':00');if(r.repeat==='daily'&&x<now)x.setDate(x.getDate()+1);if(r.repeat==='weekly'){x.setDate(x.getDate()+(Number(r.weekday)-x.getDay()+7)%7);if(x<now)x.setDate(x.getDate()+7)}return {...r,next:x}}).filter(r=>r.next>=now).sort((a,b)=>a.next-b.next)}
